const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";

const [deep, vert] = await Promise.all([
  fs.readFile(S+"\\_GIG_DEEP_RESULT.json","utf8").then(JSON.parse).catch(()=>[]),
  fs.readFile(S+"\\_GIG_VERTICAL_RESULT.json","utf8").then(JSON.parse).catch(()=>[])
]);

// 只保留真能看到活的
const GOOD = /活多且带价|活多|有活|有价格/;
const alive = [];
for (const o of [...deep, ...vert]) {
  if (GOOD.test(String(o.verdict))) {
    alive.push({
      name: o.name, host: o.host, url: o.url||("https://"+o.host),
      type: o.type||"", verdict: String(o.verdict),
      cards: o.cards||0, money: o.moneyMentions||0
    });
  }
}
// 去重 by host
const seen = new Set();
const uniq = [];
for (const a of alive) {
  const h = String(a.host).toLowerCase().replace(/^www\./,"");
  if (seen.has(h)) continue;
  seen.add(h);
  uniq.push(a);
}
await fs.writeFile(S+"\\_GIG_ALIVE.json", JSON.stringify(uniq,null,1), "utf8");
return { total: uniq.length, list: uniq.map(u=>u.name+" ("+u.verdict+")") };
